import React from 'react';

import type { VisibilityCheckboxProps } from './VisibilityCheckbox.js';
import { VisibilityCheckbox } from './VisibilityCheckbox.js';
import type { ColumnMinInstance } from '../../../types/internal-table-types.js';
import { ColumnVisibilityConfig } from '../../../types/table-config-types.js';
import { findColumnInstance } from '../../../utils/column-utils.js';
import { getCheckedState } from '../../../utils/visibility-utils.js';

/**
 * Generates column checkboxes based on the given information.
 *
 * @param columnVisibility - column visibility information.
 * @param columns - column information.
 * @param activeFilterValue - columns whose names partially match this filter will be excluded (case-insensitive).
 * @param checkboxOnChange - called when checkbox state for a column changes.
 * @returns array of checkboxes and a number indicating how many are not visible.
 */
export function generateColumnCheckboxes(
  columnVisibility: ColumnVisibilityConfig,
  columns: ColumnMinInstance[],
  checkboxOnChange: { (accessor: string, checked: boolean): void },
  createVisibilityCheckbox: (
    props: VisibilityCheckboxProps,
  ) => React.ReactElement,
): { columnCheckboxes: React.ReactElement[]; hiddenColumnCount: number } {
  let hiddenColumnCount = 0;
  const columnCheckboxes: React.ReactElement[] = [];
  const columnVisibilityEntries = Object.keys(columnVisibility);
  for (const entry of columnVisibilityEntries) {
    const identifier = entry;
    const findResult = findColumnInstance(columns, identifier);

    if (findResult) {
      const isGroup = findResult.columns;
      const checkedState = getCheckedState(findResult, columnVisibility);
      if (checkedState === false && !isGroup) {
        hiddenColumnCount++;
      }
      const header = findResult.Header;
      const colId = findResult.id;
      const columnName = typeof header === 'string' ? header : colId;

      const checkboxProps = {
        name: columnName,
        accessorOrId: identifier,
        checked: checkedState,
        checkboxOnChange,
      };

      if (checkboxProps !== undefined) {
        columnCheckboxes.push(createVisibilityCheckbox(checkboxProps));
      }
    }
  }

  return { columnCheckboxes, hiddenColumnCount };
}

/**
 * Extracted to function to enable mocking in test.
 *
 * @returns visibility checkbox with given props
 */
export function createVisibilityCheckbox(props: VisibilityCheckboxProps) {
  return <VisibilityCheckbox key={props.accessorOrId} {...props} />;
}
